-- Schéma initial GesStock 3.0 (généré par Hibernate à partir des entités).
-- Sur une base existante créée par ddl-auto=update, Flyway positionne la baseline à 1 et saute ce script.
create table approvisionnements (date_approvisionnement date, fournisseur_id bigint, id bigint not null auto_increment, session_caisse_id bigint, utilisateur_id bigint, version bigint not null, numero varchar(60) not null, statut enum ('ANNULE','BROUILLON','RECU'), primary key (id)) engine=InnoDB;
create table article (prix decimal(19,4) not null, prix_achat decimal(19,4) not null, quantite integer not null check ((quantite>=0)), seuil_alerte integer not null check ((seuil_alerte>=0)), categorie_id bigint, id bigint not null auto_increment, unite_mesure_id bigint, reference varchar(60) not null, nom varchar(150) not null, primary key (id)) engine=InnoDB;
create table categories_articles (active bit not null, id bigint not null auto_increment, parent_id bigint, nom varchar(100) not null, description varchar(500), primary key (id)) engine=InnoDB;
create table clients (id bigint not null auto_increment, telephone varchar(30), nom varchar(120) not null, email varchar(180), adresse varchar(255), primary key (id)) engine=InnoDB;
create table dettes_clients (date_creation date not null, montant_initial decimal(19,4) not null, montant_regle decimal(19,4) not null, client_id bigint not null, id bigint not null auto_increment, vente_id bigint, version bigint not null, statut enum ('ANNULEE','EN_COURS','PARTIELLEMENT_REGLEE','REGLEE') not null, primary key (id)) engine=InnoDB;
create table fournisseurs (id bigint not null auto_increment, telephone varchar(30), nom varchar(120) not null, email varchar(180), adresse varchar(255), primary key (id)) engine=InnoDB;
create table journal_activites (date_activite datetime(6) not null, entite_id bigint, id bigint not null auto_increment, utilisateur_id bigint, adresse_ip varchar(64), action varchar(80) not null, entite varchar(80) not null, details varchar(2000), primary key (id)) engine=InnoDB;
create table ligne_approvisionnements (prix_unitaire decimal(19,4) not null, quantite integer not null check ((quantite>=1)), approvisionnement_id bigint not null, article_id bigint not null, id bigint not null auto_increment, primary key (id)) engine=InnoDB;
create table lignes_proforma (montant_ligne decimal(19,4) not null, prix_unitaire decimal(19,4) not null, quantite integer not null check ((quantite>=1)), remise_unitaire decimal(19,4) not null, article_id bigint not null, id bigint not null auto_increment, proforma_id bigint not null, promotion_id bigint, unite_vente_id bigint, primary key (id)) engine=InnoDB;
create table lignes_vente (prix_unitaire decimal(19,4), quantite integer not null check ((quantite>=1)), remise_unitaire decimal(19,4), article_id bigint not null, id bigint not null auto_increment, promotion_id bigint, unite_vente_id bigint, vente_id bigint not null, primary key (id)) engine=InnoDB;
create table mouvements_caisse (montant decimal(19,4) not null, date_mouvement datetime(6) not null, effectue_par_id bigint not null, id bigint not null auto_increment, session_caisse_id bigint not null, beneficiaire varchar(120) not null, motif varchar(500) not null, type enum ('SORTIE') not null, primary key (id)) engine=InnoDB;
create table mouvements_stock (quantite integer not null check ((quantite>=1)), stock_apres integer not null check ((stock_apres>=0)), stock_avant integer not null check ((stock_avant>=0)), approvisionnement_id bigint, article_id bigint not null, date_mouvement datetime(6) not null, id bigint not null auto_increment, session_caisse_id bigint, utilisateur_id bigint, vente_id bigint, reference_document varchar(40), commentaire varchar(500), type enum ('AJUSTEMENT_NEGATIF','AJUSTEMENT_POSITIF','ENTREE_APPROVISIONNEMENT','RETOUR_CLIENT','RETOUR_FOURNISSEUR','SORTIE_VENTE') not null, primary key (id)) engine=InnoDB;
create table proformas (date_emission date not null, date_expiration date, montant_total decimal(19,4) not null, client_id bigint, id bigint not null auto_increment, utilisateur_id bigint, numero varchar(50) not null, statut enum ('ACCEPTEE','BROUILLON','CONVERTIE','ENVOYEE','EXPIREE','REFUSEE') not null, primary key (id)) engine=InnoDB;
create table promotion_articles (article_id bigint not null, promotion_id bigint not null) engine=InnoDB;
create table promotion_categories (categorie_id bigint not null, promotion_id bigint not null) engine=InnoDB;
create table promotions (active bit not null, valeur decimal(19,4) not null, debut datetime(6) not null, fin datetime(6) not null, id bigint not null auto_increment, nom varchar(120) not null, type enum ('MONTANT_FIXE','POURCENTAGE') not null, primary key (id)) engine=InnoDB;
create table reglements_clients (montant decimal(19,4) not null, client_id bigint not null, date_reglement datetime(6) not null, dette_id bigint not null, id bigint not null auto_increment, session_caisse_id bigint, utilisateur_id bigint, reference varchar(80), mode_reglement enum ('AUTRE','CARTE','CHEQUE','ESPECES','MOBILE_MONEY','VIREMENT') not null, primary key (id)) engine=InnoDB;
create table roles (id bigint not null auto_increment, name varchar(30) not null, primary key (id)) engine=InnoDB;
create table sessions_caisse (fond_de_caisse decimal(19,4) not null, journee date not null, montant_cloture decimal(19,4), fermee_le datetime(6), fermee_par_id bigint, id bigint not null auto_increment, ouverte_le datetime(6) not null, ouverte_par_id bigint not null, code varchar(50), statut enum ('FERMEE','OUVERTE') not null, primary key (id)) engine=InnoDB;
create table statistiques_journalieres (chiffre_affaires decimal(19,4) not null, journee date not null, montant_reglements decimal(19,4) not null, nombre_ventes integer not null check ((nombre_ventes>=0)), derniere_miseajour datetime(6) not null, id bigint not null auto_increment, primary key (id)) engine=InnoDB;
create table unites_mesure (id bigint not null auto_increment, code varchar(20) not null, libelle varchar(80) not null, primary key (id)) engine=InnoDB;
create table unites_vente (active bit not null, facteur_conversion decimal(19,6) not null, prix_vente decimal(19,4), article_id bigint not null, id bigint not null auto_increment, unite_mesure_id bigint not null, code varchar(30), primary key (id)) engine=InnoDB;
create table utilisateur_roles (role_id bigint not null, utilisateur_id bigint not null, primary key (role_id, utilisateur_id)) engine=InnoDB;
create table utilisateurs (actif bit not null, id bigint not null auto_increment, role varchar(30) not null, username varchar(80) not null, password varchar(255) not null, primary key (id)) engine=InnoDB;
create table vente (montant_ht decimal(19,4), montant_recu decimal(19,4), montant_total decimal(19,4), montant_tva decimal(19,4), prix_total decimal(19,4), prix_unit decimal(19,4), quantite integer not null, taux_tva decimal(7,4), venteacredit bit not null, article_id bigint, client_id bigint, date_vente datetime(6), id bigint not null auto_increment, proforma_id bigint, promotion_id bigint, session_caisse_id bigint, utilisateur_id bigint, version bigint not null, code varchar(50), mode_reglement enum ('AUTRE','CARTE','CHEQUE','ESPECES','MOBILE_MONEY','VIREMENT'), statut enum ('ANNULEE','BROUILLON','VALIDEE'), primary key (id)) engine=InnoDB;
